def transform(grid):
    H, W = len(grid), len(grid[0])

    # 1. Identify Cross (Line Row and Col)
    # The Line Color appears in exactly one full row and one full column.
    # BG might appear in many.
    line_color = None
    line_r, line_c = -1, -1

    colors = set()
    for r in range(H):
        for c in range(W):
            colors.add(grid[r][c])

    # Find the color that forms a single full row and single full column
    for c in colors:
        r_count = 0
        c_count = 0
        for r in range(H):
            if all(grid[r][x] == c for x in range(W)):
                r_count += 1
        for col_c in range(W):
            if all(grid[x][col_c] == c for x in range(H)):
                c_count += 1
        if r_count == 1 and c_count == 1:
            line_color = c
            for r in range(H):
                if all(grid[r][x] == c for x in range(W)):
                    line_r = r
            for col_c in range(W):
                if all(grid[x][col_c] == c for x in range(H)):
                    line_c = col_c
            break

    # 2. Identify Background and Figure
    bg_counts = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != line_color:
                bg_counts[grid[r][c]] = bg_counts.get(grid[r][c], 0) + 1
    bg_color = max(bg_counts, key=bg_counts.get)

    # 3. Locate Source Quadrant (where the Figure is)
    # Check quadrants for cells != line_color and != bg_color
    quad_counts = {"TL": 0, "TR": 0, "BL": 0, "BR": 0}

    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            if val != line_color and val != bg_color:
                if r < line_r and c < line_c: quad_counts["TL"] += 1
                elif r < line_r and c > line_c: quad_counts["TR"] += 1
                elif r > line_r and c < line_c: quad_counts["BL"] += 1
                elif r > line_r and c > line_c: quad_counts["BR"] += 1

    source = max(quad_counts, key=quad_counts.get)

    # 4. Extract Pattern P from Source Quadrant
    if source == "TL":
        r_min, r_max = 0, line_r
        c_min, c_max = 0, line_c
    elif source == "TR":
        r_min, r_max = 0, line_r
        c_min, c_max = line_c + 1, W
    elif source == "BL":
        r_min, r_max = line_r + 1, H
        c_min, c_max = 0, line_c
    elif source == "BR":
        r_min, r_max = line_r + 1, H
        c_min, c_max = line_c + 1, W

    h_p = r_max - r_min
    w_p = c_max - c_min

    P = []
    for r in range(h_p):
        row = []
        for c in range(w_p):
            val = grid[r_min + r][c_min + c]
            if val != bg_color: # It's the Figure
                row.append(line_color)
            else:
                row.append(bg_color)
        P.append(row)

    # 5. Construct Blocks based on Reflection Logic
    def reflect_h(m): return [row[::-1] for row in m]
    def reflect_v(m): return m[::-1]
    def reflect_hv(m): return reflect_h(reflect_v(m))

    b_tl, b_tr, b_bl, b_br = None, None, None, None

    if source == "TL":
        b_tl, b_tr, b_bl, b_br = P, reflect_h(P), reflect_v(P), reflect_hv(P)
    elif source == "TR":
        b_tl, b_tr, b_bl, b_br = reflect_h(P), P, reflect_hv(P), reflect_v(P)
    elif source == "BL":
        b_tl, b_tr, b_bl, b_br = reflect_v(P), reflect_hv(P), P, reflect_h(P)
    elif source == "BR":
        b_tl, b_tr, b_bl, b_br = reflect_hv(P), reflect_v(P), reflect_h(P), P

    # 6. Assemble Output Grid (Size H-1 x W-1)
    out = []
    for _ in range(H - 1):
        out.append([0] * (W - 1))

    # Fill Top-Left and Top-Right
    for r in range(line_r):
        # TL block
        for c in range(line_c):
            out[r][c] = b_tl[r][c]
        # TR block
        for c in range(line_c, W - 1):
            out[r][c] = b_tr[r][c - line_c]

    # Fill Bottom-Left and Bottom-Right
    for r in range(line_r, H - 1):
        # BL block (mapped from index r - line_r)
        idx = r - line_r
        for c in range(line_c):
            out[r][c] = b_bl[idx][c]
        # BR block
        for c in range(line_c, W - 1):
            out[r][c] = b_br[idx][c - line_c]

    return out
